"""
Transparent Execution Proxy
"""
import socket
import importlib.util
import os
import sys
import types
import inspect
import Pyro5.api

def is_local_module(module):
    """  
    Check if a module is a local module by comparing its file path  
    with the current working directory.  
    Params  
         module : types.ModuleType. The module to check. 
    Returns:  
        bool : 
            True if the module is local module, False otherwise.      
    """
    try:
        # Get the file path of the module
        module_file = inspect.getfile(module)
        
        # Convert both paths to absolute paths
        current_dir = os.path.abspath(os.getcwd())
        module_path = os.path.abspath(module_file)

        # Check if the module path starts with the current directory path
        return module_path.startswith(current_dir)  
    except TypeError:
        return False
    except ValueError:
        # Handle cases where module_file might not be a valid path
        return False 

def is_empty_file_module(module):
    """  
    Check if a module corresponds to an empty file.  
 
    Params  
        module : types.ModuleType. The module to check.  

    Returns:  
        bool  
            True if the module is from an empty file, False otherwise.  
    """    
    return module and (  
        hasattr(module, "__file__")  # Check if the module has a file  
        and os.path.isfile(module.__file__)  # Ensure it's a file  
        and os.path.getsize(module.__file__) == 0  # Check if the file is empty  
    )

def get_local_modules(skip_modules=None) -> list:
    """  
    Identify all local modules and retrieve them.
    Params  
        skip_modules : The modules or module names to skip.
        
    Returns
        A list of local modules.    
    """
    local_modules = []

    modules_copy = list(sys.modules.items()) 
    skip_modules =  [getattr(module, "__name__", module) for module in skip_modules] if skip_modules else None
    for module_name, module in modules_copy: 
        if module and (not skip_modules or (module_name not in skip_modules)) and is_local_module(module) and not is_empty_file_module(module):
            try: 
                local_modules.append(module)
            except (OSError, TypeError):
                pass

    return local_modules

class TransparentExecutionProxy:  
    def __init__(self, host = "localhost", port = 9090,  transfer_local_modules = True, modules_to_share: list = None, 
                additional_classes: list = None, source_dict: dict = None, other_codes: list = None, skip_modules: list = None):
        """
        Initializes an instance of the TransparentExecutionProxy class. 

        This class is designed to facilitate transparent execution of code or tasks   
        across a remote or distributed environment, with options to share modules,   
        classes, and other code components between the local and remote environments.  

        Params:  
        ----------
        host : str, optional  
            The hostname or IP address of the remote server to connect to.   Defaults to "localhost".  
            If the host is localhost, execute locally.  If the host is remote, connect to the Pyro5 server.
        
        port : int, optional  
            The port number to use for the connection. Defaults to 9090.  
        
        transfer_local_modules : bool, optional  
            If True, local Python modules will be transferred to the remote environment   
            to ensure compatibility. Defaults to True.  
        
        modules_to_share : list, optional  
            A list of specific module names (as strings) to share with the remote environment.   
            If None, all necessary modules will be shared automatically. Defaults to None.  
        
        additional_classes : list, optional  
            A list of additional class objects to share with the remote environment.   
            These classes will be made available for execution on the remote side. Defaults to None.  
        
        source_dict : dict, optional  
            A dictionary of variables or objects to share with the remote environment.   
            The keys represent variable names, and the values are the corresponding objects. Defaults to None.  
        
        other_codes : list, optional  
            A list of strings containing additional Python code snippets to execute or share   
            with the remote environment. This can be used to define custom functions or logic. Defaults to None.  
        
        skip_modules : list, optional  
            A list of module names (as strings) to exclude from being transferred to the remote environment.   
            This is useful for avoiding unnecessary or conflicting modules. Defaults to None.  

        Notes:  
        ----------
        - This method sets up the initial configuration for the proxy, ensuring that the   
        necessary components (modules, classes, variables, etc.) are prepared for remote execution.  
        - The `transfer_local_modules` flag and `modules_to_share`/`skip_modules` lists provide   
        fine-grained control over which modules are shared with the remote environment.  
        """

        self.host = host
        self.port = port
        self.remote_executor = None
        self.imported_modules=[]
        self.source_dict = source_dict
        self.other_codes = other_codes
        self.is_local = True if host == "127.0.0.1" or host == "localhost" else False
        self.transfer_local_modules = transfer_local_modules
        self.is_available = True

        if modules_to_share:
            for module in modules_to_share:
                self.imported_modules.append(module)
        if transfer_local_modules:
            local_modules = get_local_modules()
            if local_modules:
                if self.imported_modules:
                    seen = set(self.imported_modules)
                    for module in local_modules:
                        if not module in seen:
                            self.imported_modules.append(module)
                else:
                    self.imported_modules = local_modules

        dynamic_module = self.create_module_from_components(class_list=additional_classes, source_dict=source_dict, source_code_str_list=other_codes)
        self.imported_modules.append(dynamic_module)

        if not self.__module__ in skip_modules:
            skip_modules.append(self.__module__)
        if not "__main__" in skip_modules:
            skip_modules.append('__main__') 
        skip_modules = [getattr(module, "__name__", module) for module in skip_modules]
    
        if skip_modules and self.imported_modules:
            self.imported_modules  = [module for module in self.imported_modules if not isinstance(module,  types.ModuleType) or 
                                      (getattr(module, "__name__", None) not in skip_modules and not is_empty_file_module(module))]

        if self.is_local:
            self._localise_modules(self.imported_modules)
        elif self.is_host_reachable(host, port):
            # Connect to the remote Pyro5 server using the correct object ID
            uri = f"PYRO:RemoteExecutor@{host}:{port}"
            self.remote_executor = Pyro5.api.Proxy(uri)
            self.remote_executor.reset()
            self.transfer_modules()
        else:
            print("Host is not available!")
            self.is_available = False
            #raise

    @staticmethod
    def create_module_from_components(class_list, source_dict, source_code_str_list, module_name="ad_hoc_dynamic_module"):  
        """  
        Create a module object from a list of classes, a dictionary, and a list of source code strings.  
        
        :param class_list: A list of class objects to include in the module.  
        :param source_dict: A dictionary of variables to include in the module.  
        :param source_code_str_list: A list of Python code strings to execute in the module.  
        :param module_name: The name to assign to the module.  
        :return: A module object containing the provided components.  
        """  
        
        # Combine all source code into a single string  
        combined_source_code = ""    
        if class_list:  
            for cls in class_list:  
                cls_source = inspect.getsource(cls)  
                combined_source_code += cls_source + "\n\n"  
        
        # Add dictionary variables as source code  
        if source_dict:  
            for key, value in source_dict.items():  
                combined_source_code += f"{key} = {repr(value)}\n"  
            combined_source_code += "\n"  
        
        # Add additional source code strings  
        if source_code_str_list:  
            for code_str in source_code_str_list:  
                combined_source_code += code_str + "\n\n" 

        #
        if module_name not in sys.modules:
            # Create a new module object if not existing  
            # Add the module to sys.modules so it can be retrieved by name   
            module = types.ModuleType(module_name)
            sys.modules[module_name] = module    
        else:
            module = sys.modules[module_name]
        
        # Store the combined source code in a custom attribute for later use  
        module.__source__ = combined_source_code

        # Execute the combined source code in the module's namespace  
        exec(combined_source_code, module.__dict__)
         
        return module

    @staticmethod
    def is_host_reachable(host, port):
        """  
        Check if the remote host is reachable.  
        """  
        try:  
            with socket.create_connection((host, port), timeout=2):
                return True
        except (socket.timeout, ConnectionRefusedError, OSError):
            return False

    def _localise_modules(self, shared_modules):
        if isinstance(shared_modules, list):
            for module_or_object in shared_modules:
                if isinstance(module_or_object, str):  
                    # Import module by name  
                    try:  
                        module = importlib.import_module(module_or_object)
                        globals()[module_or_object] = module  
                    except ImportError as e:  
                        raise ImportError(f"Failed to import module '{module_or_object}': {e}") 
                else:
                    # Register Python object (e.g., function, class, or instance)  
                    object_name = getattr(module_or_object, "__name__", str(module_or_object)) 
                    globals()[object_name] = module_or_object 
        elif isinstance(shared_modules, dict):
            globals().update(shared_modules)
    
    def setup_modules(self, modules):
        """  
        Set up the modules.  
        """  
        if self.remote_executor:
            # Execute remotely
            return self.remote_executor.setup_modules(modules)  
        else:
            # Execute locally
            return self._localise_modules(modules)

    def transfer_modules(self):
        """  
        Extract the shared functions and classes from the module and send them to the remote server (or execute locally).  
        """  
        try:  
            if not (self.imported_modules or self.source_dict or self.other_codes):
                raise ValueError("No shared function or module provided.")
            def custom_getsource(obj):  
                """  
                Custom implementation of inspect.getsource to handle dynamically created modules.  
                """  
                # Check if the object is a module and has a __source__ attribute  
                if isinstance(obj, types.ModuleType) and hasattr(obj, "__source__"):  
                    return obj.__source__  
                # Fallback to the original getsource function  
                return inspect.getsource(obj) 
            module_dict = {module.__name__: custom_getsource(module) for module in self.imported_modules}
            self.setup_modules(module_dict)
        except Exception as e:
            print(f"Error sending shared functions or modules to the remote server: {e}")  
            raise 

    def execute_code(self, code):
        """  
        Execute arbitrary Python code transparently.  
        """  
        if not code:
            return
        if self.remote_executor:
            # Execute remotely
            return self.remote_executor.execute(code)
        else:
            # Execute locally
            exec_globals = sys.modules["__main__"].__dict__  # Use the calling module's globals  
            if isinstance(code, dict):
                for src in code.values():
                    exec(src, exec_globals)
            elif isinstance(code, list):
                for src in code: 
                    exec(src, exec_globals)
            else:
                exec(code, exec_globals)
            return exec_globals 

    def __getattr__(self, name):  
        """  
        Intercept attribute access to dynamically call functions.  
        """  
        print(f"__getattr__ called for: {name}")  # Debugging: Track which attribute is being accessed  

        # Check if the requested attribute is already a method in the proxy  
        if name in self.__dict__:  
            print(f"Attribute '{name}' found in proxy's __dict__. Returning it directly.")  
            return self.__dict__[name]  

        # Define the method to handle function calls  
        def method(*args, **kwargs):  
            print(f"method called for: {name} with args: {args}, kwargs: {kwargs}")  # Debugging: Track function calls
                    # First, check if the function exists in the current context  
            calling_globals = sys.modules["__main__"].__dict__

            if self.remote_executor:  
                print(f"Executing {name} remotely...")  
                result = self.remote_executor.run_function(name, *args, **kwargs)
                return result
            else:  
                print(f"Executing {name} locally...")  
                # Access the function from the calling module's globals  
                calling_globals = sys.modules["__main__"].__dict__  
                func = calling_globals.get(name)  

                # Ensure the function is resolved and is not proxy-based  
                if func is None or not callable(func):  
                    raise ValueError(f"Function '{name}' not found or is not callable in the current context.")  

                # Call the resolved function directly  
                print(f"Function '{name}' resolved successfully. Calling it now...")  
                return func(*args, **kwargs)  # Directly call the original function  

        # Cache the resolved method to prevent repeated resolution  
        self.__dict__[name] = method  
        print(f"Returning method for: {name}")  
        return method

    def __iter__(self):  
        """  
        Prevent the proxy from being treated as iterable.  
        """  
        raise TypeError(f"'{type(self).__name__}' object is not iterable") 

# Global variable to store the original functions  
_original_functions = {}  

def enable_transparent_execution(proxy):
    """  
    Replace global function definitions with proxy-based versions in the calling module.  
    """  
    global _original_functions  

   # Get the global namespace of the calling module
    calling_globals = sys.modules["__main__"].__dict__
    
    shared_modules = proxy.imported_modules
    # Replace global functions with proxy-based versions
    for module in shared_modules:
        for func_name in dir(module):
            func = getattr(module, func_name) 
            if (inspect.getmodule(func) == module or hasattr(module, "__source__"))  and callable(func):
                # Save the original function (if it exists)  
                _original_functions[func_name] = calling_globals.get(func_name)

                # Replace the global function with a wrapper function  
                def create_proxy_function(func_name):  
                    def proxy_function(*args, **kwargs):  
                        print(f"Proxy function called for: {func_name} with args: {args}, kwargs: {kwargs}")
                        if proxy.is_local and hasattr(module, func_name):
                            print(f"Call the local function of {func_name}")
                            method = getattr(module, func_name)
                        else:
                            # Call the proxy's __getattr__ method to resolve the function
                            method = getattr(proxy, func_name)
                            print(f"Call the proxy's __getattr__ method to resolve the function for {func_name}: {method}")
                        return method(*args, **kwargs)
                    return proxy_function

                # Assign the wrapper function to the global namespace
                calling_globals[func_name] = create_proxy_function(func_name)
        if not proxy.is_local:
            sys.modules[module.__name__] = proxy
            calling_globals[module.__name__] = proxy
    print("Transparent execution enabled: functions replaced with proxy versions.")
    
def disable_transparent_execution():
    """  
    Restore the original global function definitions in the calling module.  
    """  
    global _original_functions  

    # Get the global namespace of the calling module  
    calling_globals = sys.modules["__main__"].__dict__

    for func_name, func in _original_functions.items():  
        calling_globals[func_name] = func  # Restore the original function  

    _original_functions.clear()
    print("Transparent execution disabled: functions restored to original versions.")
